 `<circle cx="171" cy="93" r="22" fill="#f6e7be" stroke="${d.accent}"/><path d="M23 136H78M50 109V163" stroke="${d.accent}" opacity=".4"/><path d="M50 155L166 109L180 142L66 184Z" fill="${d.color}" stroke="${d.accent}" stroke-width="3"/><path d="M45 155L56 181L69 176L59 150Z" fill="#5b6a6a"/><path d="M161 107L177 101L195 142L178 148Z" fill="#c5a576" stroke="${d.accent}" stroke-width="3"/><path d="M115 162V199M91 275L115 199L140 276M115 199V281" stroke="${d.accent}" stroke-width="6"/><circle cx="115" cy="199" r="8" fill="#e2bb78"/><path d="M61 284Q125 270 184 284" stroke="${d.accent}" fill="none"/>`,
 `<path d="M54 187H174V217Q165 252 114 252Q63 250 54 217Z" fill="#f6f1db" stroke="${d.accent}" stroke-width="3"/><path d="M173 195Q211 181 207 211Q202 233 171 227" fill="none" stroke="${d.accent}" stroke-width="7"/><ellipse cx="114" cy="187" rx="60" ry="15" fill="#aa835a" stroke="${d.accent}" stroke-width="3"/><path d="M62 217Q84 205 108 218T168 215" stroke="${d.color}" stroke-width="7" fill="none"/><path d="M70 230Q93 220 112 232T160 232" stroke="${d.color}" stroke-width="3" fill="none"/><ellipse cx="121" cy="259" rx="81" ry="13" fill="#d4c39f" stroke="${d.accent}" stroke-width="2"/><path d="M92 157Q76 136 94 117M126 158Q145 136 128 110M151 146Q164 131 156 120" stroke="${d.color}" fill="none" stroke-width="3"/>`,
 `<path d="M39 150L18 130L21 179L43 163" fill="${d.accent}"/><ellipse cx="123" cy="147" rx="91" ry="46" fill="${d.color}" stroke="${d.accent}" stroke-width="3"/><path d="M33 147H214M123 103Q61 144 122 191M123 102Q182 144 123 191" fill="none" stroke="#e8c79b" stroke-width="3"/><path d="M86 188L96 223M164 187L152 223" stroke="${d.accent}" stroke-width="3"/><path d="M87 220H163L151 244H100Z" fill="#836a53"/>${[106,124,142].map(x=>`<rect x="${x}" y="225" width="9" height="9" fill="#edd8ac"/>`).join('')}<path d="M43 274Q82 244 126 268T226 263M25 78H77M183 79H220" stroke="#c4ae8a" fill="none" stroke-width="3"/>`
